import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"lib-* repos are language packages, not crates","description":"","frontmatter":{"title":"`lib-*` repos are language packages, not crates","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed — 2026-10-28. Owners: every `lib-*` repo, `host` (loader),\\n`automation` (gates)."},"headers":[],"relativePath":"handl/project/adrs/0160-lib-repos-are-language-packages.md","filePath":"vendored/handl/project/adrs/0160-lib-repos-are-language-packages.md"}'),a={name:`handl/project/adrs/0160-lib-repos-are-language-packages.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0160-lib-repos-are-language-packages-not-crates" tabindex="-1">ADR-0160: <code>lib-*</code> repos are language packages, not crates <a class="header-anchor" href="#adr-0160-lib-repos-are-language-packages-not-crates" aria-label="Permalink to “ADR-0160: lib-* repos are language packages, not crates”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>Treat every <code>lib-*</code> repo as a Handl package with a fixed shape, and delete the Rust shells as the loader learns to fetch deps.</strong></p><ol><li><p><strong>Repo shape is fixed</strong> (all 113): <code>pkg.hnl</code> · <code>src/**/*.hnl</code> · <code>README.md</code> · <code>LICENSE</code> (MIT) · <code>ci.sh</code> · <code>bupha.toml</code>, and no <code>.github/</code>.</p><p><strong>The 89 repos whose payload is <code>.hnl</code> carry no <code>Cargo.toml</code> and no <code>src/lib.rs</code>.</strong> The 24 whose <em>implementation</em> is Rust — the <code>-native</code>, <code>-c</code>, <code>-js</code> backends and <code>lib-lang-*</code> substrate adapters — keep their crate: for them the crate is the port, not transport. The distinction is mechanical: a repo with <code>.hnl</code> sources is a package; a repo with none is a backend.</p></li><li><p><strong>License is MIT only</strong>, one <code>LICENSE</code> file. <code>LICENSE-APACHE</code>/<code>LICENSE-MIT</code> pairs fold into it; <code>license = &quot;MIT OR Apache-2.0&quot;</code> disappears with the crates.</p></li><li><p><strong>CI is bupha-only</strong>: root <code>ci.sh</code> (the repo&#39;s gate) + a committed <code>bupha.toml</code> with <code>runner.kind = &quot;script&quot;</code>, <code>cmd = &quot;bash ci.sh&quot;</code> and <code>status.context = &quot;ci/bupha&quot;</code>.</p></li><li><p><strong>The shell is a bug, not a feature.</strong> It is removed in the same change that gives the loader git deps — never repo-by-repo, because a repo whose shell is gone while the loader cannot fetch it becomes unbuildable for its consumers.</p></li><li><p><strong>Consumers move to packages</strong>: <code>engine-test</code> (and any other Rust consumer) loads the module through the loader instead of <code>include_str!</code>.</p></li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The <code>lib-*</code> split (ADR-0128) made each stdlib port a repo. The contract is a Handl package: <code>pkg.hnl</code> (<code>{ deps, modules, entry? }</code>) plus <code>.hnl</code> sources. The intent was explicit — &quot;Rust in stdlib is transitional&quot; (stdlib migration plan §1), and the target layout is:</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Feature-gate the shells</strong> — Cargo resolves and <em>fetches</em> optional/dev git</li><li><strong>Vendor the <code>.hnl</code> into each consumer</strong> — duplicates the source and loses the</li><li><strong>Publish to crates.io</strong> — out of scope by decision; the whole org installs by</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Good:</strong> a package is <code>pkg.hnl</code> + <code>.hnl</code>; adding a port needs no Rust; the</li><li><strong>Cost:</strong> P1 is loader work in <code>plugin-lib-handl</code>, and P2/P3 touch consumers.</li><li><strong>Risk:</strong> a repo with <code>pkg.hnl</code> and no consumer contract (no <code>axiom</code> file) is</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>lib-*</code> — where this is true.</li><li><code>lib-lang-*</code> — where this is true.</li><li><code>engine-test</code> — where this is true.</li><li><code>plugin-lib-handl</code> — where this is true.</li><li><code>lib-pred/src/lib.rs</code> — where this is true.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0160-lib-repos-are-language-packages.html"><code>design/0160-lib-repos-are-language-packages.md</code></a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};